/**
 * npm run bundle:analyze [-- --dir dist --top 25] (round 4 B14): where the bytes of a build come from. Reads the hidden
 * source maps (`vite build` writes them) and attributes every generated byte of each chunk to the source file the
 * mapping points at, so there is no plugin to install. Prints per chunk its size and the biggest sources, and
 * writes nothing. The numbers are minified bytes before gzip.
 */
import { readFileSync, readdirSync } from 'node:fs';
import { join, resolve } from 'node:path';

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const B64_INDEX = new Map([...B64].map((c, i) => [c, i]));

/** Decodes one VLQ segment list ("AAAA,CAAC") into arrays of numbers. */
export function decodeSegments(line: string): number[][] {
  const out: number[][] = [];
  for (const seg of line.split(',')) {
    if (!seg) continue;
    const nums: number[] = [];
    let shift = 0;
    let value = 0;
    for (const ch of seg) {
      const digit = B64_INDEX.get(ch)!;
      value += (digit & 31) << shift;
      if (digit & 32) shift += 5;
      else {
        nums.push(value & 1 ? -(value >> 1) : value >> 1);
        shift = 0;
        value = 0;
      }
    }
    out.push(nums);
  }
  return out;
}

export interface SourceBytes {
  source: string;
  bytes: number;
}

/** Generated bytes per source file for one chunk: each mapped span runs to the next mapping on its line. */
export function attribute(code: string, map: { sources: string[]; mappings: string }): SourceBytes[] {
  const lines = code.split('\n');
  const totals = new Map<string, number>();
  let src = 0;
  map.mappings.split(';').forEach((line, row) => {
    const text = lines[row] ?? '';
    let col = 0;
    let prev: { src: number; col: number } | null = null;
    const flush = (end: number) => {
      if (!prev) return;
      const name = map.sources[prev.src] ?? '(unknown)';
      totals.set(name, (totals.get(name) ?? 0) + Math.max(0, end - prev.col));
    };
    for (const seg of decodeSegments(line)) {
      const newCol = col + seg[0]!;
      flush(newCol);
      col = newCol;
      if (seg.length >= 4) {
        src += seg[1]!;
        prev = { src, col };
      } else prev = null;
    }
    flush(Buffer.byteLength(text));
    // Sources and other deltas carry over between lines, columns do not.
  });
  return [...totals].map(([source, bytes]) => ({ source, bytes })).sort((a, b) => b.bytes - a.bytes);
}

/** `../../node_modules/three/src/x.js` -> `three`, `../../src/game.ts` -> `src/game.ts`. */
export function sourceGroup(source: string): string {
  const m = /node_modules\/((?:@[^/]+\/)?[^/]+)/.exec(source);
  if (m) return m[1]!;
  const s = /src\/(.*)$/.exec(source);
  return s ? `src/${s[1]}` : source;
}

function main(): void {
  const arg = (name: string) => {
    const i = process.argv.indexOf(`--${name}`);
    return i >= 0 ? process.argv[i + 1] : undefined;
  };
  const dir = resolve(arg('dir') ?? 'dist', 'assets');
  const top = Number(arg('top') ?? 15);
  let total = 0;
  for (const name of readdirSync(dir).filter((n) => n.endsWith('.js')).sort()) {
    let map: { sources: string[]; mappings: string };
    try {
      map = JSON.parse(readFileSync(join(dir, `${name}.map`), 'utf8'));
    } catch {
      continue;
    }
    const code = readFileSync(join(dir, name), 'utf8');
    const size = Buffer.byteLength(code);
    total += size;
    console.log(`\n${name}  ${(size / 1024).toFixed(1)} kB`);
    const groups = new Map<string, number>();
    for (const s of attribute(code, map)) groups.set(sourceGroup(s.source), (groups.get(sourceGroup(s.source)) ?? 0) + s.bytes);
    for (const [g, bytes] of [...groups].sort((a, b) => b[1] - a[1]).slice(0, top)) console.log(`  ${(bytes / 1024).toFixed(1).padStart(8)} kB  ${g}`);
  }
  console.log(`\nTotal JS: ${(total / 1024).toFixed(1)} kB`);
}

if (process.argv[1]?.endsWith('analyze.ts')) main();
